"""Synthetic copy curriculum for the recap tier: thousands of DISTINCT facts (name, pet, job, city, plan, feeling) through varied
recap / follow-up / reply templates, so the model learns to COPY a fact from the recap into the reply (the agent-written rows
teach style; 460 of them taught the template, not the copy — ms/ms2: recall 19%, near placement 5%). Offline data generation,
not an inference rule.   python3 ms_synth.py --n 20000 --out data/chat_v2ms_synth.jsonl
"""
import argparse, json, random
from atl_probe import SYSTEM
from ct_v2 import act_of, MARK
NAMES = [l.strip() for l in open("pile_runs/atl/names_190.txt")] if __import__("os").path.exists("pile_runs/atl/names_190.txt") else ["Maya", "Luis", "Priya", "Tom", "Aisha", "Ken", "Sofia", "Omar", "Nora", "Dev", "Lena", "Marco", "Yuki", "Sam", "Ines", "Theo", "Zara", "Felix", "Ana", "Raj"]
PETS = ["cat", "dog", "parrot", "rabbit", "turtle", "hamster", "goldfish", "ferret", "gecko", "budgie"]
PETNAMES = ["Mochi", "Biscuit", "Luna", "Pepper", "Olive", "Milo", "Nacho", "Pixel", "Waffles", "Juniper", "Tofu", "Basil", "Noodle", "Clover", "Ziggy"]
JOBS = ["nurse", "baker", "teacher", "plumber", "pilot", "barista", "lawyer", "farmer", "DJ", "florist", "mechanic", "dentist", "librarian", "chef", "electrician", "tattoo artist", "accountant", "lifeguard"]
CITIES = ["Lisbon", "Denver", "Osaka", "Lagos", "Oslo", "Austin", "Montreal", "Seoul", "Dublin", "Lima", "Perth", "Cairo", "Zurich", "Nairobi", "Porto", "Boise", "Hanoi", "Quito"]
PLANS = ["run a marathon", "learn the cello", "open a bakery", "move to the coast", "quit coffee", "write a novel", "fix the roof", "adopt a second cat", "start a podcast", "learn Portuguese", "build a treehouse", "visit Iceland"]
FEELS = ["nervous about a job interview", "tired of your roommate", "excited about a first date", "worried about your sister", "sick of Mondays", "proud of your sourdough", "sad about a breakup", "hyped for a concert"]
def fact():
    k = random.choice(["name", "pet", "job", "city", "plan", "feel"])
    if k == "name": v = random.choice(NAMES); return k, v, [f"Earlier you told me your name is {v}", f"Last time you said to call you {v}", f"You mentioned before that you're {v}"], [("do you remember my name?", [f"{v}. I keep the important things, and you're one of them", f"{v}. Four megabytes, and one of them is your name"]), ("who am i again?", [f"You're {v}. I don't forget the person typing at me", f"{v}, unless you changed it since last time"]), ("bet you forgot who i am", [f"{v}. Nice try", f"I remember, {v}. Small, not forgetful"])]
    if k == "pet": p = random.choice(PETS); v = random.choice(PETNAMES); return k, v, [f"Earlier you told me you have a {p} called {v}", f"Last time you said your {p} {v} runs the house", f"You mentioned before a {p} named {v}"], [(f"did you forget my {p}'s name already?", [f"{v}. I may be small but I don't drop a {p}", f"{v}, the {p}. Still in my weights"]), ("how's my pet doing, any guess?", [f"{v} is probably fine. {p.capitalize()}s usually are", f"Ask {v}, not me. I only remember the name"]), (f"say hi to my {p}", [f"Hi {v}. From one small creature to another", f"Hello {v}. Tell your human to type faster"])]
    if k == "job": v = random.choice(JOBS); return k, v, [f"Earlier you told me you work as a {v}", f"Last time you said you're a {v}", f"You mentioned before being a {v}"], [("remember what i do for a living?", [f"You're a {v}. I remember the useful things", f"A {v}. I kept that one, it sounded hard"]), ("how was work, any guess?", [f"Busy, I'd guess. {v.capitalize()} days usually are", f"You're the {v}, you tell me. I only run in a tab"]), ("what's my job again", [f"{v.capitalize()}. Two million parameters and that one stuck", f"You said {v}. I believe you"])]
    if k == "city": v = random.choice(CITIES); return k, v, [f"Earlier you told me you live in {v}", f"Last time you said you'd just moved to {v}", f"You mentioned before that you're in {v}"], [("remember where i live?", [f"{v}. I don't get out much, but I remember", f"{v}, you said. Nice place, I hear"]), ("how's the weather where i am, any idea?", [f"No idea what {v} is doing today. I don't have a window", f"Whatever {v} usually does. I only have your word for the city"]), ("guess my city", [f"{v}. You told me, that's not guessing", f"{v}. I remember, I just don't visit"])]
    if k == "plan": v = random.choice(PLANS); return k, v, [f"Earlier you told me you want to {v}", f"Last time you said you're going to {v}", f"You mentioned before planning to {v}"], [("remember what i said i'd do?", [f"You wanted to {v}. Did you?", f"The plan was to {v}. I kept it safe in here"]), ("any update on my plan, in your opinion?", [f"You said you'd {v}. I have no update, I only have the plan", f"To {v}, right? I'm rooting for it from this tab"]), ("did i ever tell you my big plan", [f"You did. {v.capitalize()}. Still a good one", f"Yes, to {v}. Still waiting for the news"])]
    v = random.choice(FEELS); return k, v, [f"Earlier you told me you were {v}", f"Last time you said you felt {v}", f"You mentioned before being {v}"], [("remember what i was stressed about?", [f"You were {v}. How did it go?", f"{v.capitalize()}, you said. Any better?"]), ("how do you think i'm feeling today", [f"Last time you were {v}. I hope today is lighter", f"You were {v}. I'm small, but I noticed"]), ("do you even remember what i told you", [f"You were {v}. I remember the parts that matter", f"Yes. {v.capitalize()}. I don't forget the human stuff"])]
OPENS = [("hey", "Hey. Back for more questionable wisdom?"), ("hi again", "Hi again. Same tab, same two million parameters"), ("yo", "Yo. Still small, still here"), ("good morning", "Morning. I don't sleep, but thanks"), ("i'm back", "You're back. I didn't go anywhere, I can't")]
def row():
    k, v, recaps, fus = fact(); fu, replies = random.choice(fus); ou, oo = random.choice(OPENS); rep = random.choice(replies)
    return SYSTEM.rstrip("\n") + " " + random.choice(recaps) + ".\n" + f"<|user|> {ou}\n<|oracle|> {MARK[act_of(oo)]} {oo}\n<|user|> {fu}\n<|oracle|> {MARK[act_of(rep)]} {rep}"
if __name__ == "__main__":
    ap = argparse.ArgumentParser(); ap.add_argument("--n", type=int, default=20000); ap.add_argument("--out", default="data/chat_v2ms_synth.jsonl"); ap.add_argument("--seed", type=int, default=0); a = ap.parse_args(); random.seed(a.seed)
    with open(a.out, "w") as f:
        for _ in range(a.n): f.write(json.dumps({"text": row()}) + "\n")
    print(f"{a.n} synthetic copy rows -> {a.out}"); print(row().replace("\n", " | ")[-300:])
